import { describe, expect, it, vi, afterEach } from "vitest";
import request from "supertest";
import express from "express";
import { app } from "../src/server.js";
import { rateLimiter } from "../src/middleware/rateLimiter.js";

describe("Rate limiter", () => {
  it("sends 429 once the limit is exceeded", async () => {
    const hits = Array.from({ length: 60 }, () => request(app).get("/notes"));
    const allowed = await Promise.all(hits);
    expect(allowed.every((res) => res.status === 200)).toBe(true);

    const blocked = await request(app).get("/notes");
    expect(blocked.status).toBe(429);
    expect(blocked.body).toEqual({ error: "Too many requests, please try again later" });
  });

  it("sends rate-limit headers", async () => {
    const res = await request(app).get("/notes");
    expect(res.headers["x-ratelimit-limit"]).toBe("60");
    expect(Number(res.headers["x-ratelimit-remaining"])).toBeLessThanOrEqual(60);
  });

  it("resets the count once the window elapses", async () => {
    vi.useFakeTimers();
    afterEach(() => vi.useRealTimers());

    const mini = express();
    mini.use(rateLimiter({ windowMs: 1_000, max: 2 }));
    mini.get("/x", (_req, res) => res.sendStatus(200));

    await request(mini).get("/x");
    await request(mini).get("/x");
    const blocked = await request(mini).get("/x");
    expect(blocked.status).toBe(429);

    vi.advanceTimersByTime(1_001);
    const afterReset = await request(mini).get("/x");
    expect(afterReset.status).toBe(200);
  });
});

